INSERT INTO public.provider_blog_posts (provider_id,provider_name,title,excerpt,url,image_url,category,published_at,source_type,source_url,last_seen_at) VALUES
('sports-blood-tests','EDGE','What is Active B12 & why is it important for athletes?','Active B12 is the bioavailable form of vitamin B12 and is needed for red blood cell production, nerve function, and energy metabolism, all of which are an essential part of athletic performance. For athletes, a deficiency in active B12 can result in fatigue, muscle weakness, reduced endurance, poor coordination, and even brain fog. These symptoms are often misattributed to overtraining, when in reality they may stem from an underlying nutritional imbalance.','https://www.sportsbloodtests.co.uk/biomarkers/what-is-active-b12-why-is-it-important-for-athletes/',NULL,'Vitamins','2025-05-22','edge-index','https://www.sportsbloodtests.co.uk/biomarkers/','2026-11-07T00:05:00Z'),
('sports-blood-tests','EDGE','What is Albumin & why is it important for athletes?','Albumin is the most abundant protein in your blood plasma. It’s produced by the liver and plays helps to maintain fluid balance, transport hormones and nutrients, and support recovery from physical stress. While often overlooked, albumin can provide insight into your nutritional status, inflammation, hydration, and overall recovery – all key factors for athletic performance.','https://www.sportsbloodtests.co.uk/biomarkers/what-is-albumin-why-is-it-important-for-athletes/',NULL,'Hormones','2025-05-22','edge-index','https://www.sportsbloodtests.co.uk/biomarkers/','2026-11-07T00:05:00Z'),
('sports-blood-tests','EDGE','What is Cortisol & why is it important for athletes?','Cortisol is your body’s primary stress hormone and is essential for managing energy, inflammation, and recovery. For athletes, cortisol is a double-edged sword: too little and your body can’t respond to stress; too much and it starts to break down muscle, increase fatigue, and hinder performance. Understanding and managing cortisol is key to unlocking peak performance.','https://www.sportsbloodtests.co.uk/biomarkers/what-is-cortisol-why-is-it-important-for-athletes/',NULL,'Hormones','2025-05-22','edge-index','https://www.sportsbloodtests.co.uk/biomarkers/','2026-11-07T00:05:00Z'),
('sports-blood-tests','EDGE','What is Creatine Kinase & why is it important for athletes?','Creatine kinase (CK) is an enzyme released into the blood when muscle tissue is damaged. It’s a key marker for muscle stress and recovery, helping athletes understand how their body is responding to training loads. While elevated CK levels after intense workouts are normal, persistently high levels may point to overtraining, inadequate recovery, or muscle strain — all of which can compromise performance and increase injury risk.','https://www.sportsbloodtests.co.uk/biomarkers/what-is-creatine-kinase-why-is-it-important-for-athletes/',NULL,'Mental Health','2025-05-22','edge-index','https://www.sportsbloodtests.co.uk/biomarkers/','2026-11-07T00:05:00Z'),
('sports-blood-tests','EDGE','What is Creatinine & why is it important for athletes?','Creatinine is a waste product formed when creatine, a key compound in muscle energy metabolism, breaks down. It’s filtered by the kidneys and excreted in urine, making it a useful marker of kidney function. For athletes, creatinine levels offer insight not just into kidney health but also hydration status, muscle mass, and recovery. However, interpreting creatinine in athletes requires context – particularly for those with high muscle mass, high protein diets or using creatine supplements.','https://www.sportsbloodtests.co.uk/biomarkers/what-is-creatinine-why-is-it-important-for-athletes/',NULL,'Wellness','2025-05-22','edge-index','https://www.sportsbloodtests.co.uk/biomarkers/','2026-11-07T00:05:00Z'),
('sports-blood-tests','EDGE','What is eGFR & why is it important for athletes?','eGFR (estimated glomerular filtration rate) measures how well your kidneys are filtering waste from your blood. It’s calculated using creatinine levels, age, sex, and body size — providing a key indicator of kidney function. For athletes, especially those training at high intensity or using supplements, eGFR helps flag early signs of kidney stress. It’s particularly important when monitoring hydration, recovery, or the impact of prolonged endurance training.','https://www.sportsbloodtests.co.uk/biomarkers/what-is-egfr-why-is-it-important-for-athletes/',NULL,'Mental Health','2025-05-22','edge-index','https://www.sportsbloodtests.co.uk/biomarkers/','2026-11-07T00:05:00Z'),
('sports-blood-tests','EDGE','What is Ferritin & why is it important for athletes?','Ferritin is a blood protein that transports iron, making it a vital marker of your body’s iron reserves. For athletes, especially endurance and female athletes, the overall iron status, reflected by ferritin, is closely tied to red cell production which impacts oxygen delivery, energy, and performance capacity. However, iron is ubiquitous in the body and is also involved in immune function, hair health, sleep and even thyroid function. Low ferritin levels can silently sap endurance, delay recovery, and increase fatigue, long before anaemia develops. That’s why ferritin is one of the most important biomarkers to monitor regularly in sports.','https://www.sportsbloodtests.co.uk/biomarkers/what-is-ferritin-why-is-it-important-for-athletes/',NULL,'Thyroid','2025-05-22','edge-index','https://www.sportsbloodtests.co.uk/biomarkers/','2026-11-07T00:05:00Z'),
('sports-blood-tests','EDGE','What is Follicle-stimulating hormone (FSH) & why is it important for athletes?','Follicle-stimulating hormone (FSH) is a reproductive hormone that regulates the development of eggs in women and sperm in men. For athletes, especially those experiencing menstrual changes, low testosterone, or symptoms of hormonal imbalance, FSH is a critical marker. It provides insight into reproductive health, hormonal function, and, indirectly, energy availability, all of which can affect training, recovery, and performance.','https://www.sportsbloodtests.co.uk/biomarkers/what-is-follicle-stimulating-hormone-fsh-why-is-it-important-for-athletes/',NULL,'Hormones','2025-05-22','edge-index','https://www.sportsbloodtests.co.uk/biomarkers/','2026-11-07T00:05:00Z'),
('sports-blood-tests','EDGE','What is Free Testosterone & why is it important for athletes?','Testosterone is a key anabolic hormone that supports muscle growth, strength, energy, and recovery. “Free testosterone” refers to the active form circulating in your blood, which is available to tissues and responsible for its performance-enhancing effects. For athletes, free testosterone levels provide a clearer picture of hormonal status than total testosterone alone, especially when symptoms like fatigue, low strength gains, or poor recovery arise.','https://www.sportsbloodtests.co.uk/biomarkers/what-is-free-testosterone-why-is-it-important-for-athletes/',NULL,'Hormones','2025-05-22','edge-index','https://www.sportsbloodtests.co.uk/biomarkers/','2026-11-07T00:05:00Z'),
('sports-blood-tests','EDGE','What is Haemoglobin & why is it important for athletes?','Haemoglobin is the protein in red blood cells responsible for carrying oxygen from your lungs to your muscles. For athletes, it’s one of the most important markers of aerobic capacity, endurance, and recovery. If your haemoglobin is low, your muscles receive less oxygen, leading to early fatigue, reduced performance, and slower recovery. Optimising haemoglobin levels is essential for sustained, high-output training and competition.','https://www.sportsbloodtests.co.uk/biomarkers/what-is-haemoglobin-why-is-it-important-for-athletes/',NULL,'Wellness','2025-05-22','edge-index','https://www.sportsbloodtests.co.uk/biomarkers/','2026-11-07T00:05:00Z'),
('sports-blood-tests','EDGE','What is hs-CRP & why is it important for athletes?','hs-CRP is a marker of inflammation in the body. While some inflammation is a normal part of the training and recovery cycle, persistently elevated levels may indicate systemic stress, poor recovery, or even underlying illness. For athletes, tracking hs-CRP can provide insight into whether the body is adapting well to training or tipping into overtraining or inflammation-driven fatigue.','https://www.sportsbloodtests.co.uk/biomarkers/what-is-hs-crp-why-is-it-important-for-athletes/',NULL,'Mental Health','2025-05-22','edge-index','https://www.sportsbloodtests.co.uk/biomarkers/','2026-11-07T00:05:00Z'),
('sports-blood-tests','EDGE','What is Luteinising hormone (LH) & why is it important for athletes?','Luteinising hormone (LH) plays a central role in reproductive health and hormonal balance. In women, LH regulates ovulation; in men, it stimulates testosterone production. For athletes, LH is a powerful indicator of how well the body is coping with training demands, nutrition, and stress. Disrupted LH levels are often linked to energy deficiency, overtraining, or hormonal imbalance, impacting performance, recovery, and long-term health.','https://www.sportsbloodtests.co.uk/biomarkers/what-is-luteinising-hormone-lh-why-is-it-important-for-athletes/',NULL,'Hormones','2025-05-22','edge-index','https://www.sportsbloodtests.co.uk/biomarkers/','2026-11-07T00:05:00Z'),
('sports-blood-tests','EDGE','What is Oestradiol & why is it important for athletes?','Oestradiol is the primary form of oestrogen in premenopausal women and plays a vital role in regulating the menstrual cycle, bone health, and metabolism. For female athletes, it’s a key indicator of hormonal balance and long-term performance health. In men, oestradiol is produced in smaller amounts, primarily through the conversion of testosterone. It contributes to bone health, cardiovascular function, and mood regulation — all important for performance and recovery. Low oestradiol in women is commonly linked to irregular periods, energy deficiency, reduced bone density, and impaired recovery, particularly in endurance or high-volume training environments. In men, imbalances can affect libido, bone strength, and overall wellbeing, making regular monitoring useful for athletes pushing their physical limits.','https://www.sportsbloodtests.co.uk/biomarkers/what-is-oestradiol-why-is-it-important-for-athletes/',NULL,'Hormones','2025-05-22','edge-index','https://www.sportsbloodtests.co.uk/biomarkers/','2026-11-07T00:05:00Z'),
('sports-blood-tests','EDGE','What is Progesterone & why is it important for athletes?','Progesterone is a key reproductive hormone in women, primarily produced after ovulation during the second half of the menstrual cycle (luteal phase). It plays a vital role in regulating menstrual health, supporting fertility, and balancing oestrogen. For female athletes, progesterone is also a marker of hormonal resilience, energy balance, and recovery. Persistently low levels can indicate disrupted cycles, under-fuelling, or the early signs of Relative Energy Deficiency in Sport (RED-S) .','https://www.sportsbloodtests.co.uk/biomarkers/what-is-progesterone-why-is-it-important-for-athletes/',NULL,'Hormones','2025-05-22','edge-index','https://www.sportsbloodtests.co.uk/biomarkers/','2026-11-07T00:05:00Z'),
('sports-blood-tests','EDGE','What is Prolactin & why is it important for athletes?','Prolactin is a hormone produced by the pituitary gland, mainly known for its role in lactation. However, in both men and women, elevated prolactin can disrupt the balance of sex hormones like testosterone and oestrogen , affecting mood, libido, recovery, and performance. Prolactin can reveal hidden hormonal imbalances, particularly in athletes experiencing fatigue, low libido, or cycle irregularities.','https://www.sportsbloodtests.co.uk/biomarkers/what-is-prolactin-why-is-it-important-for-athletes/',NULL,'Hormones','2025-05-22','edge-index','https://www.sportsbloodtests.co.uk/biomarkers/','2026-11-07T00:05:00Z'),
('sports-blood-tests','EDGE','What is Red Blood Cell Count (RBC) & why is it important for athletes?','Red blood cells (RBCs) carry oxygen from your lungs to your muscles and carbon dioxide away from your tissues back to the lungs. A higher RBC count typically means better oxygen delivery, enhancing endurance, stamina, and recovery. RBC count is a key performance biomarker for endurance athletes, especially when monitored alongside haemoglobin and haematocrit.','https://www.sportsbloodtests.co.uk/biomarkers/what-is-red-blood-cell-count-rbc-why-is-it-important-for-athletes/',NULL,'Gut Health','2025-05-22','edge-index','https://www.sportsbloodtests.co.uk/biomarkers/','2026-11-07T00:05:00Z'),
('sports-blood-tests','EDGE','What is Sex Hormone Binding Globulin (SHBG) & why is it important for athletes?','Sex Hormone Binding Globulin (SHBG) is a protein made by the liver that binds to sex hormones, primarily testosterone and oestrogen , in the bloodstream. It controls how much of these hormones are “free” and biologically active. For athletes, SHBG plays a role in hormone availability. Even if your total testosterone or oestrogen levels are normal, high SHBG can reduce the amount of free hormone available to support muscle growth, energy, recovery, and libido.','https://www.sportsbloodtests.co.uk/biomarkers/what-is-sex-hormone-binding-globulin-shbg-why-is-it-important-for-athletes/',NULL,'Hormones','2025-05-22','edge-index','https://www.sportsbloodtests.co.uk/biomarkers/','2026-11-07T00:05:00Z'),
('sports-blood-tests','EDGE','What is Thyroid Stimulating Hormone & Why Is it Important for Athletes?','TSH controls thyroid hormone production, regulating metabolism, energy, and temperature balance. Abnormal TSH levels can signal underactive or overactive thyroid function, both of which can impact endurance, recovery, and weight management.','https://www.sportsbloodtests.co.uk/biomarkers/what-is-thyroid-stimulating-hormone-why-is-it-important-for-athletes/',NULL,'Thyroid','2025-05-22','edge-index','https://www.sportsbloodtests.co.uk/biomarkers/','2026-11-07T00:05:00Z'),
('sports-blood-tests','EDGE','What is Thyroxine (T4) & Why Is it Important for Athletes?','Free T4 (thyroxine) is one of the two main hormones produced by the thyroid gland. It plays a central role in regulating metabolism, energy production, and protein synthesis — all of which are crucial for athletic performance. Free T4 is the inactive precursor to T3 (the active thyroid hormone). Together, they support energy output, recovery, and endurance.','https://www.sportsbloodtests.co.uk/biomarkers/what-is-thyroxine-t4-why-is-it-important-for-athletes/',NULL,'Thyroid','2025-05-22','edge-index','https://www.sportsbloodtests.co.uk/biomarkers/','2026-11-07T00:05:00Z'),
('sports-blood-tests','EDGE','What is Total Testosterone & Why Is it Important for Athletes?','Total testosterone reflects the overall level of testosterone in the bloodstream, both bound and free. It’s a primary driver of muscle growth, strength, libido, energy, and recovery in both men and women. For athletes, suboptimal testosterone (even within the “normal” range) can blunt training progress and recovery.','https://www.sportsbloodtests.co.uk/biomarkers/what-is-total-testosterone-why-is-it-important-for-athletes/',NULL,'Hormones','2025-05-22','edge-index','https://www.sportsbloodtests.co.uk/biomarkers/','2026-11-07T00:05:00Z'),
('sports-blood-tests','EDGE','What is Triiodothyronine (T3) & Why Is it Important for Athletes?','Free T3 is the active form of thyroid hormone, directly responsible for regulating metabolism, energy use, and thermogenesis. It’s converted from T4 and is the most metabolically powerful thyroid hormone. Athletes with disrupted T3 levels may struggle with recovery, fatigue, and poor adaptation to training.','https://www.sportsbloodtests.co.uk/biomarkers/what-is-triiodothyronine-t3-why-is-it-important-for-athletes/',NULL,'Thyroid','2025-05-22','edge-index','https://www.sportsbloodtests.co.uk/biomarkers/','2026-11-07T00:05:00Z'),
('sports-blood-tests','EDGE','What is Urea & Why Is it Important for Athletes?','Urea is a waste product formed from the breakdown of protein. It’s filtered by the kidneys and is a useful indicator of hydration, training load, and protein metabolism in athletes. High levels can signal dehydration or muscle breakdown. Low levels may suggest under-fuelling or poor protein intake.','https://www.sportsbloodtests.co.uk/biomarkers/what-is-urea-why-is-it-important-for-athletes/',NULL,'Wellness','2025-05-22','edge-index','https://www.sportsbloodtests.co.uk/biomarkers/','2026-11-07T00:05:00Z'),
('sports-blood-tests','EDGE','What is Vitamin D & Why Is it Important for Athletes?','Vitamin D is a fat-soluble vitamin that plays a crucial role in immune health, muscle function, inflammation control, and bone strength. Many athletes, especially in the UK, are deficient, particularly during winter months. Low vitamin D affects muscle strength, increases injury risk, and prolongs recovery.','https://www.sportsbloodtests.co.uk/biomarkers/what-is-vitamin-d-why-is-it-important-for-athletes/',NULL,'Vitamins','2025-05-22','edge-index','https://www.sportsbloodtests.co.uk/biomarkers/','2026-11-07T00:05:00Z'),
('sports-blood-tests','EDGE','What is White Blood Cell (WBC) Count & Why Is it Important for Athletes?','White blood cells (WBCs) are key components of the immune system, helping the body fight off illness and recover from physical stress. For athletes, WBC count can reveal how well the immune system is coping with training, travel, or illness.','https://www.sportsbloodtests.co.uk/biomarkers/what-is-white-blood-cell-wbc-count-why-is-it-important-for-athletes/',NULL,'Mental Health','2025-05-22','edge-index','https://www.sportsbloodtests.co.uk/biomarkers/','2026-11-07T00:05:00Z')
